#include "PluginProcessor.h"
#include <iostream>
#include <stdexcept>
int main(int argc,char**){try{std::unique_ptr<juce::ScopedJuceInitialiser_GUI> gui;if(argc>1)gui=std::make_unique<juce::ScopedJuceInitialiser_GUI>();MasteringProcessor p;p.prepareToPlay(48000,512);juce::MidiBuffer midi;juce::AudioBuffer<float> b(2,512);auto* bypass=p.state.getParameter("bypass");bypass->setValueNotifyingHost(1);for(int c=0;c<2;++c)for(int i=0;i<512;++i)b.setSample(c,i,.125f);p.processBlock(b,midi);if(b.getSample(0,500)!=.125f)throw std::runtime_error("processor bypass");auto* gain=p.state.getParameter("input");gain->setValueNotifyingHost(gain->convertTo0to1(9));juce::MemoryBlock data;p.getStateInformation(data);MasteringProcessor restored;restored.setStateInformation(data.getData(),static_cast<int>(data.getSize()));if(std::abs(restored.state.getRawParameterValue("input")->load()-9)>1e-4)throw std::runtime_error("session recall");if(restored.state.getRawParameterValue("bypass")->load()!=1)throw std::runtime_error("bypass recall");if(p.getParameters().size()!=37)throw std::runtime_error("parameter count");if(argc>1){std::unique_ptr<juce::AudioProcessorEditor> editor(p.createEditor());bool adjusted=false;for(int i=0;i<editor->getNumChildComponents();++i)if(auto* slider=dynamic_cast<juce::Slider*>(editor->getChildComponent(i)))if(slider->getName()=="Input"){slider->setValue(6,juce::sendNotificationSync);adjusted=true;}if(!adjusted||std::abs(p.state.getRawParameterValue("input")->load()-6)>1e-4)throw std::runtime_error("UI parameter attachment");auto image=editor->createComponentSnapshot(editor->getLocalBounds());juce::FileOutputStream stream(juce::File("/tmp/tg-editor.png"));if(!juce::PNGImageFormat().writeImageToStream(image,stream))throw std::runtime_error("Editor snapshot");if(image.getWidth()!=1260||image.getHeight()!=804)throw std::runtime_error("Editor size");std::cout<<"Native editor rendered to /tmp/tg-editor.png\n";}std::cout<<"Processor bypass, 37 host parameters and session recall passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
